    "questionEn": "Q62 (2025 CSE GS-I). With reference to Modern Indian History & Freedom Struggle, consider the following statements:\n1. It is mandated under the statutory provisions and framework established by the Union Government.\n2. The institutional oversight is conducted periodically in alignment with international standard guidelines.\n3. All sovereign states and union territories in India are covered unconditionally under its scope.\nWhich of the statements given above is/are correct?",
    "questionHi": "प्रश्न 62 (2025 सिविल सेवा प्रारंभिक परीक्षा)। Modern Indian History & Freedom Struggle के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:\n1. यह केंद्र सरकार द्वारा स्थापित वैधानिक प्रावधानों और ढांचे के तहत अनिवार्य है।\n2. संस्थागत निरीक्षण अंतरराष्ट्रीय मानक दिशानिर्देशों के अनुरूप समय-समय पर किया जाता है।\n3. भारत के सभी राज्य और केंद्र शासित प्रदेश बिना किसी शर्त के इसके दायरे में शामिल हैं।\nउपर्युक्त कथनों में से कौन सा/से सही है/हैं?",
